// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 0, type(uint128).max);
        unlockTime = bound(unlockTime, 0, type(uint64).max);
        uint256 totalDeposited = address(c).balance;
        (,,,,uint256 preBal) = c.Acc(address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (,,,,uint256 postBal) = c.Acc(actor);
        totalDeposited += amount;
        assertTrue(address(c).balance == totalDeposited && postBal == preBal + amount);
    }
}

