pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalDeposited;

    function setUp() public {
        c = new C(address(new Log()));
        totalDeposited = 0;
    }

    function testFuzz_property(uint96 amount, address user) public {
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        vm.assume(user != address(this));
        vm.assume(amount > 0);

        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(0);

        totalDeposited += amount;

        uint256 sumBalances = 0;
        sumBalances += c.Acc(address(this));
        sumBalances += c.Acc(user);

        assertTrue(sumBalances + address(c).balance == 2 * totalDeposited);
    }
}

