// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initBalance, uint256 depositAmount) public {
        // Bound depositAmount to a positive value to ensure a call is made.
        depositAmount = bound(depositAmount, 1, type(uint256).max);
        // Bound initial balance such that initBalance + depositAmount could overflow.
        initBalance = bound(initBalance, 0, type(uint256).max);

        address actor = address(0x123);
        // Set the actor's initial balance in the contract by first depositing initBalance.
        if (initBalance > 0) {
            vm.deal(actor, initBalance);
            vm.prank(actor);
            c.Put{value: initBalance}(0);
        }
        // Now make the Put call with depositAmount.
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(0);

        // Read the stored balance.
        ( , uint256 finalBalance) = c.Acc(actor);

        // The general property: after a Put call, the recorded balance must be at least the sum
        // of the previous balance and the deposit amount (assuming no overflow).
        // If the addition overflowed, the finalBalance would be less than initBalance + depositAmount.
        // In the reference contract, the require ensures we never reach the addition if it would overflow.
        // In the mutant, require(true) allows the overflow to occur.
        // We assert that the final balance is >= initBalance + depositAmount.
        assertTrue(finalBalance >= initBalance + depositAmount);
    }
}

