pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initBalance, uint256 sendValue) public {
        // Bound values to avoid unrealistic extremes but keep a wide range
        bound(initBalance, 0, type(uint128).max);
        bound(sendValue, 1, type(uint128).max);
        vm.assume(initBalance + sendValue > initBalance); // ensure no overflow in test setup

        // Set up initial balance for a random sender
        address sender = makeAddr("sender");
        vm.deal(sender, sendValue);
        if (initBalance > 0) {
            vm.deal(sender, initBalance);
            vm.prank(sender);
            c.Put{value: initBalance}(0);
        }

        // Record total Eth received by contract before Put
        uint256 totalEthBefore = address(c).balance;
        // Record total Acc balances before Put
        uint256 totalAccBefore = c.Acc(sender).balance;
        // Ensure we only consider the sender's Acc, but totalEth is all eth in contract.
        // The actual invariant: total balance in all Accs must equal total received eth.
        // Since other accounts can be present, we measure the change for this sender and compare with the eth increase.
        // Any overflow in Acc balance addition will cause a mismatch: balance increase < sendValue.

        vm.prank(sender);
        c.Put{value: sendValue}(0);

        uint256 totalEthAfter = address(c).balance;
        uint256 totalAccAfter = c.Acc(sender).balance;
        uint256 expectedAcc = totalAccBefore + sendValue;
        // In the reference, no overflow so expectedAcc == totalAccAfter and eth increased by sendValue.
        // In the mutant, overflow can occur making totalAccAfter < expectedAcc, while total eth still increased by sendValue.
        assertTrue(totalAccAfter == expectedAcc && totalEthAfter == totalEthBefore + sendValue);
    }
}

