        vm.deal(sender, initialBalance + additional);
        vm.startPrank(sender);
        if (initialBalance > 0) {
            c.Put{value: initialBalance}(0);
        }
        vm.stopPrank();
        uint256 balanceBeforeSecond = c.Acc(sender).balance;
        vm.startPrank(sender);
        c.Put{value: additional}(0);
        vm.warp(block.timestamp + 1 days);
        uint256 collected = balanceBeforeSecond + additional;
        bool success;
        try c.Collect(collected) { success = true; } catch { success = false; }
        vm.stopPrank();
        assertTrue(success && c.Acc(sender).balance == 0);
    }
}

