pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime) public {
        // Admissible domain: any unlockTime (no restriction needed)
        // Use a fixed caller for simplicity; the property only concerns the Put function's success/failure.
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok;
        try c.Put{value: 1 ether}(_unlockTime) { ok = true; } catch { ok = false; }
        // Property: Put must not revert. The reference C never reverts on a normal Put call
        // because the require always passes (balance addition never overflows and the check is always true).
        // The mutant removes the require, which in Solidity 0.8 still reverts on overflow inside +=,
        // but it changes behavior in edge cases where the check would have failed, potentially causing a revert.
        // However, the require itself never fails in C, so the property is that Put must always succeed.
        assertTrue(ok);
    }
}

