pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _value, address _caller) public {
        // 1. restrict to admissible domain: avoid zero-value edge-case, avoid precompile collisions
        vm.assume(_caller != address(0) && _caller != address(this) && _caller != address(c));
        vm.assume(_value > 0);
        // 2. set up the scenario
        vm.deal(_caller, _value);
        uint256 prevBalance = c.Acc(_caller).balance;
        vm.prank(_caller);
        // We need to detect if Put reverts. In the reference C, the require prevents overflow.
        // In the mutant, the overflow revert may be caught or may bubble up.
        // We wrap the call to check success.
        (bool success, ) = address(c).call{value: _value}(abi.encodeWithSignature("Put(uint256)", _unlockTime));
        // 3. invariant: if the call succeeded, the new balance must be prevBalance + _value
        if (success) {
            uint256 newBalance = c.Acc(_caller).balance;
            assertTrue(newBalance == prevBalance + _value);
        }
    }
}

