// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint128 unlockTime1, uint128 unlockTime2) public {
        // Bound amounts to admissible range (non-zero, avoid overflow)
        amount1 = bound(amount1, 1, 1 ether);
        amount2 = bound(amount2, 1, 1 ether);
        // Bound unlock times to reasonable future timestamps
        uint256 u1 = bound(uint256(unlockTime1), block.timestamp + 1, block.timestamp + 365 days);
        uint256 u2 = bound(uint256(unlockTime2), block.timestamp + 1, block.timestamp + 365 days);
        // Ensure amounts are different to trigger the overwrite bug
        vm.assume(amount1 != amount2);

        // Deploy adversarial helper: a re-entrant attacker that calls Put again during Collect
        // This is needed to observe the difference via external behavior, as the bug manifests in balance overwrite
        // which affects subsequent Collect calls and Ether transfers.
        Attacker attacker = new Attacker(address(c), u1, u2);

        // Fund attacker with both amounts
        vm.deal(address(attacker), amount1 + amount2);

        // Attacker performs two Put calls with different amounts, then triggers Collect
        attacker.attack{value: amount1 + amount2}(amount1, amount2);

        // After attack, the attacker's balance in C should be at least amount1 + amount2 if accumulating correctly.
        // The bug overwrites the balance to the second amount, making it less.
        // We check that the attacker's balance in C is >= amount1 + amount2 (true for reference, false for bug).
        ( , uint256 finalBalance) = c.Acc(address(attacker));
        assertTrue(finalBalance >= amount1 + amount2);
    }
}

contract Attacker {
    C public c;
    uint256 private u1;
    uint256 private u2;
    bool private attacked;

    constructor(address _c, uint256 _u1, uint256 _u2) {
        c = C(_c);
        u1 = _u1;
