pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 firstTime, uint256 secondTime, uint128 amount, uint32 wait) public {
        // Bound unlock times to reasonable future values to ensure all timestamps are comparable.
        uint256 now_ = block.timestamp;
        uint256 t1 = bound(firstTime, now_ + 1, type(uint128).max);
        uint256 t2 = bound(secondTime, now_ + 1, type(uint128).max);
        // Bound deposit amount to avoid overflow and ensure it meets Collect min balance.
        uint256 amt = bound(amount, 2 ether, 1000 ether);
        // Bound wait to a safe window less than the maximum gap we might warp over.
        uint256 wait1 = bound(wait, 1, 365 days);

        // Adversarial callee that always reverts on receiving ether, so we observe revert vs success of Collect.
        Reverter r = new Reverter();
        // Use the revert helper as the caller. It will receive the withdrawal attempt.
        address actor = address(r);

        // Give the actor ether to deposit.
        vm.deal(actor, amt * 2);

        // First Put with a high unlock time.
        vm.prank(actor);
        c.Put{value: amt}(t1);

        // Second Put – the mutant overwrites unlockTime unconditionally, even with a smaller value.
        // If t2 < t1, the reference keeps max(t1, now_) >= t1, the mutant sets t2.
        // Then wait and attempt collect. The reference should hold until t1, the mutant may allow earlier.
        vm.prank(actor);
        c.Put{value: 0}(t2);

        // Warp forward to just after the earlier of the two times.
        uint256 targetTime = t1 < t2 ? t1 + 1 : t2 + 1;
        vm.warp(targetTime);

        // Try collecting the full balance. We attack via the revert helper; its fallback reverts on receive.
        // Under reference, Collect reverts if timestamp <= unlockTime; under bug, unlockTime may be smaller (t2).
        bool ok;
        try r.collectFrom(address(c), amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: If t2 < t1, the reference's unlockTime remains t1, and at targetTime (just after min(t1,t2))
        // Collect must NOT succeed (ok == false) because unlockTime has not yet passed.
        // The bug sets unlockTime to t2, making it pass, so ok may be true.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: reject ether");
    }

    // Helper to trigger collect on a target contract.
    function collectFrom(address target, uint256 amount) external {
        (bool success,) = target.call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));
        require(success, "Reverter: collect reverted");
    }
}

