contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialUnlockTime, uint256 putCallUnlockTime, uint128 collectAmount, uint32 warpTo) public {
        // 1. restrict domain: warpTo must be after the initial put so we can test a later Collect
        vm.assume(warpTo > 0);
