    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 amount, uint256 collectAmt) public {
        // Bind amount to a reasonable range to keep balance addition safe.
        amount = bound(amount, 1, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp, type(uint64).max);
        collectAmt = bound(collectAmt, 0, amount);

        // Use a fresh EOA as the depositor/collector.
        address actor = address(uint160(uint256(keccak256(abi.encodePacked("actor", unlockTime)))));
        vm.assume(actor != address(this) && actor != address(c));

        // Fund the actor and deposit via Put.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Warp past unlockTime to allow collection.
        vm.warp(unlockTime + 1);

        // Record balances before Collect for invariant check.
        uint256 actorBalBefore = Acc_getter(actor);
        uint256 contractBalBefore = address(c).balance;
        uint256 minSum = c.MinSum();

        // Attempt Collect.
        vm.prank(actor);
        try c.Collect(collectAmt) { } catch { }

        uint256 actorBalAfter = Acc_getter(actor);
        uint256 contractBalAfter = address(c).balance;

        // Compute expected actor balance after operation:
        //   P: acc.balance = amount;
        //      after Collect (if conditions met): acc.balance = amount - collectAmt
        //      contract balance = amount - collectAmt (only if collect succeeds)
        //   M: acc.balance always stays 0 after Put; after Collect acc.balance stays 0.
        //   Therefore invariant: actorBalAfter + (uncollected portion) should match deposit minus collected amount
        //   Specifically, for P: actorBalAfter == amount - collected (where collected = collectAmt if conditions met else 0)
        //   For M: actorBalAfter == 0 regardless.
        // We check that in P, actorBalAfter == (amount - (contractBalBefore - contractBalAfter))
        // because contractBalBefore - contractBalAfter = amount transferred out (collected).

        // The reference property: actor's Acc balance equals the original deposit minus the amount actually withdrawn.
        uint256 withdrawn = contractBalBefore - contractBalAfter;
        bool holds = (actorBalAfter == amount - withdrawn);

        assertTrue(holds);
    }

    function Acc_getter(address a) internal view returns (uint256) {
        ( , uint256 bal) = c.Acc(a);
        return bal;
    }
}

