contract LogHelper {
    function HistoryLen(address cAddr) external view returns (uint256) {
        (bool ok, bytes memory data) = cAddr.staticcall(abi.encodeWithSignature("History(uint256)", 0));
        if (!ok) return 0;
        uint256 len = 0;
        while (true) {
            (bool ok2, bytes memory data2) = cAddr.staticcall(abi.encodeWithSignature("History(uint256)", len));
            if (!ok2 || data2.length == 0) break;
            len++;
        }
        return len;
    }

    function HistorySender(address cAddr, uint256 index) external view returns (address) {
        (bool ok, bytes memory data) = cAddr.staticcall(abi.encodeWithSignature("History(uint256)", index));
        if (!ok) return address(0);
        // The return is a struct (address Sender, string Data, uint Val, uint Time)
        // We extract the first 32 bytes (address is left-padded)
        assembly {
            let sender := mload(add(data, 32))
            return(0, sender)
        }
    }
}

