        vm.assume(collectAmt == depositAmt);
        // Restrict warp to be after unlockTime but not excessively far
        vm.assume(warpAmount > unlockTime && warpAmount <= type(uint64).max);

        address caller = address(0x1234);
        uint256 initBalance = depositAmt;
        vm.deal(caller, depositAmt);

        // Deposit: caller sends exactly depositAmt with future unlockTime
        vm.prank(caller);
        c.Put{value: depositAmt}(unlockTime);

        // Warp past unlockTime
        vm.warp(warpAmount);

        // Record balance before collection attempt
        uint256 balanceBefore = c.Acc(caller).balance;

        bool ok;
        vm.prank(caller);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = c.Acc(caller).balance;

        // If the collect attempt succeeded, balance must have decreased by collectAmt
        // otherwise balance must remain unchanged
        if (ok) {
            assert(balanceAfter == balanceBefore - collectAmt);
        } else {
            assert(balanceAfter == balanceBefore);
        }
    }
}

