pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint128 _secondAm) public {
        // We need two distinct holders: holder1 (this contract) and holder2 (an EOA)
        address holder2 = address(uint160(_am)); // fuzzed address, zero is fine
        vm.assume(holder2 != address(this) && holder2 != address(c));

        // Give both holders some ETH and have them Put to create balances
        uint256 initialBal = 10 ether;
        vm.deal(address(this), initialBal);
        vm.deal(holder2, initialBal);

        // Holder1 Puts and Collects late enough
        vm.prank(address(this));
        c.Put{value: 1 ether}(0); // unlockTime = block.timestamp
        vm.warp(block.timestamp + 1);
        // Record holder1's balance before Collect
        uint256 holder1BalBefore = c.Acc(address(this));

        vm.prank(address(this));
        c.Collect(1 ether); // self collect, should not change ETH balance

        // Holder2 Puts and tries to Collect after holder1's Collect
        vm.prank(holder2);
        c.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 1);

        uint256 contractEthBefore = address(c).balance;

        // Bound _secondAm to be at most holder2's balance (1 ether) and at least 1
        uint256 boundedSecondAm = bound(_secondAm, 1, 1 ether);
        vm.prank(holder2);
        // In reference, this Collect always succeeds because contract holds enough ETH.
        // In mutant, holder1's balance was inflated, so contract ETH might be insufficient
        // if holder1 tries to collect again, but here we let holder2 collect normally.
        // The real difference: after holder1's Collect, contract ETH is still 2 ether,
        // holder1's stored balance is 1 ether, holder2's stored balance is 1 ether.
        // In mutant, after holder1's Collect, stored balance becomes 1 + 1 = 2 ether,
        // but contract ETH is still 2 ether. Then holder2 Collects, contract ETH drops to 1,
        // but stored balances remain 2+1=3 > 1, so a future collect reverts.
        // To expose the revert: after holder2 collects, we try to collect the remaining stored balance of holder1 (which is inflated).
        bool okCollect2;
        try c.Collect(boundedSecondAm) { okCollect2 = true; } catch { okCollect2 = false; }
        assertTrue(okCollect2); // holder2's collect must succeed in reference

        // Now holder1 tries to collect its remaining stored balance (should be 0 in reference, 1 ether in mutant)
        vm.prank(address(this));
        bool okCollect1Again;
        try c.Collect(1 ether) { okCollect1Again = true; } catch { okCollect1Again = false; }
        // Reference: stored balance is 0, so Collect reverts (balance<MinSum condition fails or underflow), okCollect1Again = false.
        // Mutant: stored balance is 1 ether, Collect succeeds, transferring 1 ether, which the contract has.
        // But the rule is: after successive successful Collects, contract ETH never drops below sum of stored balances.
        // Actually, the simpler invariant: a successful Collect never causes a subsequent Collect by a second holder to revert due to insufficient ETH.
        // However, the mutant's addition doesn't immediately cause a revert on the second collect.
        // Instead, the invariant that fails is: the sum of all stored balances <= address(c).balance.
        // After both collects, check that.
        uint256 totalStored = c.Acc(address(this)) + c.Acc(holder2);
        uint256 contractEth = address(c).balance;
        assertTrue(totalStored <= contractEth);
    }
}

